import zipfile
from datetime import datetime, timezone


def _iso(timestamp):
    try:
        return datetime.fromtimestamp(timestamp, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    except (OverflowError, OSError, ValueError):
        return "1970-01-01T00:00:00Z"


def archive_records(filename):
    """Return lla-style metadata records for archive members, or None if unsupported.

    Records are flat (one per virtual member); callers apply depth and format rules.
    Their paths are rooted at the archive basename, as in lla machine output.
    """
    lower = os.fspath(filename).lower()
    if not lower.endswith((".zip", ".tar", ".tar.gz", ".tgz")):
        return None
    base = os.path.basename(os.fspath(filename))
    source = os.path.abspath(filename)
    records = {}

    def add(name, is_dir, size, timestamp, mode, explicit):
        name = name.replace("\\", "/").strip("/")
        if not name:
            return
        parts = name.split("/")
        for i in range(1, len(parts)):
            parent = "/".join(parts[:i])
            if parent not in records:
                records[parent] = (True, 0, 0, 0o755, False)
        records[name] = (is_dir, size, timestamp, mode, explicit)

    try:
        if zipfile.is_zipfile(filename):
            with zipfile.ZipFile(filename) as zf:
                for info in zf.infolist():
                    is_dir = info.is_dir()
                    try:
                        ts = datetime(*info.date_time, tzinfo=timezone.utc).timestamp()
                    except (ValueError, OverflowError):
                        ts = 0
                    mode = (info.external_attr >> 16) & 0o7777
                    if not mode:
                        mode = 0o775 if is_dir else 0o600
                    add(info.filename, is_dir, 0 if is_dir else info.file_size, ts, mode, True)
        else:
            with tarfile.open(filename, "r:*") as tf:
                for member in tf.getmembers():
                    add(member.name, member.isdir(), 0 if member.isdir() else member.size,
                        member.mtime, member.mode, True)
    except (OSError, tarfile.TarError, zipfile.BadZipFile):
        return None

    out = []
    for name in sorted(records, key=lambda s: (s.lower(), s)):
        is_dir, size, ts, mode, explicit = records[name]
        leaf = name.rsplit("/", 1)[-1]
        path = base + "/" + name
        out.append({
            "path": path, "name": leaf,
            "extension": (leaf.rsplit(".", 1)[-1] if "." in leaf and not leaf.startswith(".") else None),
            "file_type": "dir" if is_dir else "file",
            "size_bytes": int(size), "modified": _iso(ts),
            "created": None, "accessed": None, "mode_octal": format(mode, "04o"),
            "owner_user": "root", "owner_group": "root", "inode": None,
            "hard_links": None, "symlink_target": None,
