"""Timeline view formatter."""
import datetime


def timeline(items, now=None):
    now = now or datetime.datetime.now().astimezone()
    groups = {"Today": [], "Last Week": [], "Last Month": [], "Older": []}
    for item in items:
        try:
            stamp = datetime.datetime.strptime(item["modified"], "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=datetime.timezone.utc).astimezone()
        except (ValueError, KeyError):
            continue
        age = max(0, (now - stamp).total_seconds())
        days = age / 86400
        group = "Today" if stamp.date() == now.date() else "Last Week" if days < 7 else "Last Month" if days < 30 else "Older"
        if group == "Older":
            date = stamp.strftime("%b %d" + (", %Y" if stamp.year != now.year else ""))
        elif age < 60:
            date = "just now"
        elif age < 3600:
            minutes = int(age // 60)
            date = f"{minutes} min{'s' if minutes != 1 else ''} ago"
        elif age < 86400:
            hours = int(age // 3600)
            date = f"{hours} hour{'s' if hours != 1 else ''} ago"
        elif days < 7:
            count = int(days)
            date = f"{count} day{'s' if count != 1 else ''} ago"
        else:
            weeks = int(days // 7)
            date = f"{weeks} weeks ago"
        name = item.get("name", "") + ("/" if item.get("file_type") == "dir" else "")
        groups[group].append((stamp, name, date))
    out = []
    for group, entries in groups.items():
        if not entries:
            continue
        entries.sort(key=lambda x: (-x[0].timestamp(), x[1]))
        if out:
            out.append("")
        out.extend([group, "─" * 40])
        out.extend(f"{name} • {date}" for _, name, date in entries)
    return "\n".join(out)

"""Size visualization formatter."""
import os


def human(n):
    if n < 1024:
        return f"{n} B"
    if n < 1024**2:
        return f"{n / 1024:.1f} KB"
    if n < 1024**3:
        return f"{n / 1024**2:.1f} MB"
    return f"{n / 1024**3:.1f} GB"


def sizemap(items, include_dirs=False):
    rows = []
    for item in items:
        size = item.get("size_bytes", 0)
        if include_dirs and item.get("file_type") == "dir":
            path = item.get("path", item.get("name", ""))
            try:
                size = sum(os.path.getsize(os.path.join(root, name))
                           for root, _, files in os.walk(path) for name in files)
            except OSError:
                pass
        rows.append((item, size))
    total = sum(size for _, size in rows)
    rows.sort(key=lambda row: (-row[1], row[0].get("name", "")))
    output = []
    for item, size in rows:
        ratio = size / total if total else 0
        raw = ratio * 60
        full = min(60, int(raw))
        partial = 1 if full < 60 and raw > full else 0
        bar = "█" * full + ("▓" if partial else "") + "⋅" * (60 - full - partial)
        name = item.get("name", "") + ("/" if item.get("file_type") == "dir" else "")
        output.append(f"  {name:<24} {human(size):>5}  {bar} {ratio * 100:.1f}%")
    output.extend(["", f"  {'Total':<24} {human(total):>5}"])
    return "\n".join(output)

